/**
 * Generador de 70 módulos del curso LETRAS (Literatura y Lenguaje)
 * Salida:
 *   1) modules/letras.json (respaldo de datos)
 *   2) le-batch-1.ts ... le-batch-7.ts en ../prepa-premium-uv/src/data/
 */
const fs = require('fs');
const path = require('path');
const { writeBatch } = require('./gen-utils.js');

const MODULES_DIR = path.join(__dirname, 'modules');
const MODULES = [];

const B = 'basico', I = 'intermedio', A = 'avanzado';

// CRITICO: el tercer argumento de th() SIEMPRE va entre corchetes [...]
function th(level, title, lines) { return { level, title, lines }; }
function Q(question, o1, o2, o3, o4, ci, exp, dif) {
  return { question, options: [o1, o2, o3, o4], correctIndex: ci, explanation: exp, difficulty: dif };
}
function M(slug, tip, t1, t2, t3, exercises) {
  MODULES.push({ slug, tip, theory: [t1, t2, t3], illustrations: [], exercises });
}

// ============ BLOQUE 1: COMPRENSION LECTORA Y TIPOS DE TEXTO (1-10) ============

