let errores = 0;
MODULES.forEach((m, mi) => {
  const errs = [];
  if (!m.slug || !m.tip) errs.push('slug/tip vacio');
  if (m.theory.length !== 3) errs.push('theory!=' + m.theory.length);
  const lv = m.theory.map(t => t.level);
  if (!(lv[0] === 'basico' && lv[1] === 'intermedio' && lv[2] === 'avanzado')) errs.push('orden niveles');
  m.theory.forEach(t => { if (t.lines.length !== 5) errs.push('lines ' + t.level + '=' + t.lines.length); });
  if (m.exercises.length !== 21) errs.push('ejercicios=' + m.exercises.length);
  const d = { basico: 0, intermedio: 0, avanzado: 0 };
  m.exercises.forEach((qq, qi) => {
    if (qq.options.length !== 4) errs.push('opts q' + (qi + 1));
    if (!(qq.correctIndex >= 0 && qq.correctIndex <= 3)) errs.push('ci q' + (qi + 1));
    if (!(qq.difficulty in d)) errs.push('dif q' + (qi + 1)); else d[qq.difficulty]++;
  });
  if (d.basico !== 7 || d.intermedio !== 7 || d.avanzado !== 7) errs.push('dist=' + d.basico + '/' + d.intermedio + '/' + d.avanzado);
  if (errs.length) { errores++; console.error('ERROR modulo ' + (mi + 1) + ' (' + m.slug + '): ' + errs.join('; ')); }
});
if (errores > 0) { console.error('Validacion fallida en ' + errores + ' modulos'); process.exit(1); }

// Asignar ids 1..21 dentro de cada modulo
MODULES.forEach(m => m.exercises.forEach((qq, qi) => { qq.id = qi + 1; }));

// Guardar respaldo JSON
if (!fs.existsSync(MODULES_DIR)) fs.mkdirSync(MODULES_DIR, { recursive: true });
fs.writeFileSync(path.join(MODULES_DIR, 'letras.json'), JSON.stringify(MODULES), 'utf8');
console.log('modules/letras.json guardado: ' + MODULES.length + ' modulos, ' + MODULES.reduce((s, m) => s + m.exercises.length, 0) + ' preguntas');

// Generar lotes TS (10 modulos por lote => 7 lotes)
console.log('\nGenerando lotes TS:');
for (let i = 0; i < MODULES.length; i += 10) {
  const n = Math.floor(i / 10) + 1;
  writeBatch('le', n, 'leBatch' + n, MODULES.slice(i, i + 10));
}
console.log('\nListo: 70 modulos de LETRAS generados correctamente.');
